import{_ as r,l as s,o as t,c as l,v as e,p as h,x as o,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"写入网格与 shot 数","description":"","frontmatter":{"title":"写入网格与 shot 数","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/write-grid-shot-count.md","filePath":"litho/write-grid-shot-count.md","lastUpdated":1789023840000}'),E={name:"litho/write-grid-shot-count.md"};function c(m,a,_,A,u,P){const i=s("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="写入网格与-shot-数" tabindex="-1">写入网格与 shot 数 <a class="header-anchor" href="#写入网格与-shot-数" aria-label="Permalink to &quot;写入网格与 shot 数&quot;">​</a></h1><div class="epigraph"><p>地址栅量化每一条边；炮的离散尺寸量化每一次曝光。两张梯子叠在 PEC 剂量图上，才是写得出的几何。</p><footer>—— 对照 VSB 地址栅、成形孔径台阶与多束像素的写入器通称</footer></div><p><a href="/litho/mask-pec-detail">上一课</a>把剂量图拆成多层核。缺口是这张连续图必须落在硬件栅格上：地址单元、最小炮、束距。本课钉写入网格与 shot 数。落在栅格上的 CD 如何统计成整张均匀性，留给[下一课](/litho/mask-cdu）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/gdsii-oasis">GDS 的 DBU</a> 可以比写模地址栅更细。细网格上的 OPC 边会被吸到最近可写坐标，短 jog 消失，助条宽度跳一档。VSB 还叠加孔径成形的离散宽高：不是任意矩形，是台阶上的矩形。shot 数因此有两层意思：几何分割给出的炮列表，以及为了灰度或 PEC 动态范围拆成的多次曝光。</p><p>缺口是<strong>量化</strong>，不是再卷积一次背散射。把「网格 1 nm」写成「掩模 CD 精度 1 nm」，忽略了成形台阶、束斑与刻蚀。多束像素尺寸是第三张梯子：曲率半径小于若干束距，曲线 MRC 已经判不可写。</p><h3 id="过采样换的是时间" tabindex="-1">过采样换的是时间 <a class="header-anchor" href="#过采样换的是时间" aria-label="Permalink to &quot;过采样换的是时间&quot;">​</a></h3><p>地址栅加密、多遍交错扫描，可以降低量化噪声和粗糙，但 shot 数或遍数涨，<a href="/litho/mask-write-time">写入时间</a> 几乎线性涨。节点预算里 mask LER 有一截来自这张梯子，不是来自晶圆扫描机。</p><p><span class="marginnote">合同里的「写栅」要与 OPC 输出网格、MRC 最小 jog 对齐。三套数各说各话时，TAPOUT 会在 fracturing 报告里才发现边被量化掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计规则与 OPC 碎边长度必须 ≥ 可写量子（再留刻蚀偏置）。灰度 VSB 用重叠炮逼近斜边，shot 数上升，量化误差下降——要在同一张 CDU/LER 预算里验收。多束：选束距使光学通带内的边足够光滑，再停止加密。</p><p>计数：曼哈顿层用炮密度（炮/μm²）预测 VSB 时间；曲线层用像素数 × 剂量预测多束时间。两套 KPI 不要加总成一个「复杂度分数」去排产。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>量化误差是周期性的：边落在栅格之间时，CD 误差在 ±½ 格子附近跳。经 MEF 放大后进入晶圆，但通常小于光学项——除非助条本身只有两三个量子宽。PEC 剂量台阶同样离散：过稀的剂量档会在疏密交界留下条纹，像剂量域的量化噪声。</p>',14)),(t(),h(p,null,{default:o(()=>[d(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20DBU%5B%22%E8%AE%BE%E8%AE%A1%20DBU%22%5D%20--%3E%20SNAP%5B%22%E5%90%B8%E5%88%B0%E5%86%99%E6%A0%85%22%5D%0A%20%20SNAP%20--%3E%20SHAPE%5B%22VSB%20%E5%AD%94%E5%BE%84%E5%8F%B0%E9%98%B6%22%5D%0A%20%20SHAPE%20--%3E%20SHOT%5B%22shot%20%E5%88%97%E8%A1%A8%22%5D%0A%20%20SNAP%20--%3E%20PIX%5B%22%E5%A4%9A%E6%9D%9F%E5%83%8F%E7%B4%A0%22%5D%0A%20%20SHOT%20--%3E%20TIME%5B%22%E5%86%99%E5%85%A5%E6%97%B6%E9%97%B4%22%5D%0A%20%20PIX%20--%3E%20TIME%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>网格不提高 NA。加密网格不能用光学分辨率去论证，只能用写入器与检验能力论证。不要把某机型的最小炮表抄成本课常数。</p><p>后课默认：可写几何已经过栅格量化；下一课把整张版的 CD 离散与工艺残差收成 CDU。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>写栅与孔径台阶量化边与炮；多束另有束距梯子。</li><li>shot 数含分割炮与灰度/多遍拆分；直接驱动 VSB 日历。</li><li>OPC 网格、MRC jog、写栅必须对齐。</li><li>出处：VSB 地址栅与成形束通称；多束像素写入公开讨论。</li></ul>',5))])}const f=r(E,[["render",c]]);export{S as __pageData,f as default};
